<?php
function sampleStaff(string $name,string $email=''):array{if(trim($email)!==''){$u=one("SELECT * FROM users WHERE LOWER(email)=? AND active=1 AND role <> 'student'",[strtolower(trim($email))]);attRequire((bool)$u,'Tutor email not found: '.$email);return $u;}$clean=fn($n)=>strtolower(trim(preg_replace('/^(dr\.?|mr\.?|ms\.?)\s+/i','',trim($n))));$matches=array_values(array_filter(staff(),fn($u)=>$clean($u['name'])===$clean($name)));attRequire(count($matches)===1,'Enter Tutor Email to resolve faculty: '.$name);return $matches[0];}
function sampleDay(string $s):int{$short=['mon'=>'Monday','tue'=>'Tuesday','wed'=>'Wednesday','thu'=>'Thursday','fri'=>'Friday','sat'=>'Saturday','sun'=>'Sunday'];return dayNumber($short[strtolower(substr(trim($s),0,3))]??$s);}
function sampleTimeRange(string $s):array{$s=str_replace(['–','—',' to '],'-',trim($s));$parts=explode('-',$s);attRequire(count($parts)===2,'Use a time range such as 13:15-15:15.');$parse=function($v){$v=trim($v);if(preg_match('/^(\d{1,2}):?(\d{2})\s*(AM|PM)$/i',$v,$m)){attRequire((int)$m[1]>=1&&(int)$m[1]<=12,'Invalid 12-hour time.');return sprintf('%02d:%02d',((int)$m[1]%12)+(strtoupper($m[3])==='PM'?12:0),(int)$m[2]);}if(preg_match('/^(\d{1,2}):?(\d{2})$/',$v,$m))return sprintf('%02d:%02d',(int)$m[1],(int)$m[2]);throw new RuntimeException('Use explicit 24-hour times or AM/PM for both endpoints.');};attRequire((bool)preg_match('/(AM|PM)/i',$parts[0])===(bool)preg_match('/(AM|PM)/i',$parts[1]),'Specify AM/PM for both endpoints or use 24-hour times.');$a=$parse($parts[0]);$b=$parse($parts[1]);attRequire(timeValid($a)&&timeValid($b)&&$b>$a,'Invalid time range. Use 24-hour times, e.g. 15:30-17:30.');return [$a,$b];}
function consultWideHeaders():array{return ['Faculty','Modules Taught','Free Days','Mentor-Mentee Day','Mentor-Mentee Time','Academic-Related Day','Academic-Related Time','Tutor Email'];}
function wideConsultationRows(array $rows,array $context):array{
 $header=array_map('trim',array_shift($rows)??[]);$aliases=['Module(s) Taught'=>'Modules Taught','Free Day'=>'Free Days','Free Days (no classes)'=>'Free Days','Mentor Mentee Time'=>'Mentor-Mentee Time','Academic Related Day'=>'Academic-Related Day','Academic Related Time'=>'Academic-Related Time'];$header=array_map(fn($h)=>$aliases[$h]??$h,$header);
 if(in_array('Day',$header,true))return [$header,...$rows];
 foreach(array_slice(consultWideHeaders(),0,7)as $h)attRequire(in_array($h,$header,true),'Missing consultation column: '.$h);
 $expanded=[['Tutor Email','Day','Start Time','End Time','Location','Department','Term','Modules','Free Days','Kind']];
 foreach($rows as $i=>$row){if(!array_filter($row))continue;$r=array_combine($header,array_slice(array_pad($row,count($header),''),0,count($header)));$u=sampleStaff($r['Faculty'],$r['Tutor Email']??'');$slots=[];
 foreach(['Mentor-Mentee','Academic-Related']as $kind){$day=trim($r[$kind.' Day']??'');$time=trim($r[$kind.' Time']??'');if($day===''&&$time==='')continue;attRequire($day!==''&&$time!=='','Row '.($i+2).': provide both day and time.');[$start,$end]=sampleTimeRange($time);$weekday=sampleDay($day);$key=$weekday.'|'.$start.'|'.$end;if(isset($slots[$key])){$slots[$key][9].=' / '.$kind;continue;}$slots[$key]=[$u['email'],['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][$weekday],$start,$end,$context['location']??'Faculty office',$context['department']??$u['department'],$context['term']??'',$r['Modules Taught'],$r['Free Days'],$kind];}
 foreach($slots as $slot)$expanded[]=$slot;
 }return $expanded;
}
function consultationTimetableSlots(string $department):array{
 if($department===''||!in_array($department,departments(),true))return [];
 if(attReady())return all("SELECT s.*,u.name,u.department AS staff_department,COALESCE(NULLIF(d.department,''),u.department) AS department,d.term,d.modules,d.free_days,d.kind FROM slots s JOIN users u ON u.id=s.faculty_id LEFT JOIN consultation_slot_details d ON d.slot_id=s.id WHERE s.active=1 AND u.active=1 AND COALESCE(NULLIF(d.department,''),u.department)=? ORDER BY s.weekday,s.start_time,u.name",[$department]);
 return all('SELECT s.*,u.name,u.department AS department FROM slots s JOIN users u ON u.id=s.faculty_id WHERE s.active=1 AND u.active=1 AND u.department=? ORDER BY s.weekday,s.start_time,u.name',[$department]);
}
function renderConsultGrid(array $slots):void{
 $groups=[];foreach($slots as $s){$group=($s['department']?:$s['staff_department']).' · '.($s['term']??'');$key=$s['faculty_id'];$groups[$group][$key]??=['name'=>$s['name'],'modules'=>$s['modules']??'','free'=>$s['free_days']??'','mentor'=>[],'academic'=>[]];$v=['day'=>['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][$s['weekday']],'time'=>$s['start_time'].'–'.$s['end_time']];if(str_contains($s['kind']??'','Mentor'))$groups[$group][$key]['mentor'][]=$v;if(!$s['kind']||str_contains($s['kind'],'Academic'))$groups[$group][$key]['academic'][]=$v;}
 foreach($groups as $title=>$rows){echo '<h2>Faculty Visiting / Consultation Hours — '.e($title).'</h2><div class="table-wrap"><table class="consult-grid"><thead><tr><th>Faculty</th><th>Modules Taught</th><th>Free Days</th><th>Mentor-Mentee Day</th><th>Mentor-Mentee Time</th><th>Academic-Related Day</th><th>Academic-Related Time</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['modules']).'</td><td>'.e($r['free']).'</td><td>'.e(implode('; ',array_column($r['mentor'],'day'))).'</td><td>'.e(implode('; ',array_column($r['mentor'],'time'))).'</td><td>'.e(implode('; ',array_column($r['academic'],'day'))).'</td><td>'.e(implode('; ',array_column($r['academic'],'time'))).'</td></tr>';echo '</tbody></table></div>';}
}
function classPeriods():array{return [['08:00','09:00'],['09:00','10:00'],['10:00','10:15'],['10:15','11:15'],['11:15','12:15'],['12:15','13:15'],['13:15','14:15'],['14:15','15:15'],['15:15','15:30'],['15:30','16:30'],['16:30','17:30']];}
function renderClassGrid(array $u):void{$groups=[];foreach(scheduledRows()as $t){if(!$t['active']||!attVisible($u,$t))continue;foreach(sessionGroups($t)as $g){$key=$t['academic_year'].' / '.$t['semester'].' · '.$g['department'].' · '.$g['programme'].' · Year '.$g['year_level'].' '.$g['section'];$groups[$key][]=$t;}}foreach($groups as $title=>$rows){echo '<h2 class="class-heading">'.e($title).'</h2><div class="table-wrap"><table class="class-grid"><thead><tr><th>Day / Time</th>';foreach(classPeriods()as [$a,$b])echo '<th>'.e($a.'–'.$b).'</th>';echo '</tr></thead><tbody>';foreach([1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri']as $day=>$label){echo '<tr><th>'.$label.'</th>';foreach(classPeriods()as [$a,$b]){if(in_array($a,['10:00','12:15','15:15'])){echo '<td class="break">'.($a==='12:15'?'Lunch':'Break').'</td>';continue;}$cells=[];foreach($rows as $r)if($r['weekday']==$day&&$r['start_time']<$b&&$r['end_time']>$a)$cells[]=e($r['subject_code']).'<small>'.e($r['room_code'].' · '.$r['start_time'].'–'.$r['end_time']).'</small>'.($r['class_date']?'<small>'.e($r['class_date']).'</small>':'');echo '<td>'.implode('<hr>',$cells).'</td>';}echo '</tr>';}echo '</tbody></table></div><table><thead><tr><th>Module code</th><th>Module title</th><th>Tutor</th></tr></thead><tbody>';$seen=[];foreach($rows as $r){$key=$r['subject_code'].'|'.$r['staff_id'];if(isset($seen[$key]))continue;$seen[$key]=1;echo '<tr><td>'.e($r['subject_code']).'</td><td>'.e($r['subject_name']).'</td><td>'.e($r['name']).'</td></tr>';}echo '</tbody></table>';}}
function classGridTemplate():never{
 $book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Weekly class grid');$sheet->setCellValue('A1','Enter academic year, semester, department and programme on upload.');$headers=['Day/Time','0800-0900','0900-1000','Rm #','Break','1015-1115','Rm #','1115-1215','Rm #','Lunch','1315-1415','Rm #','1415-1515','Rm #','Break','1530-1630','Rm #','1630-1730','Rm #','','Module code','Module title','Tutor','Tutor Email'];foreach([1=>'I',2=>'II',3=>'III',4=>'IV']as $year=>$roman){$base=3+($year-1)*10;$sheet->setCellValue('A'.$base,'Year '.$roman.' Sem I');$sheet->fromArray([$headers],null,'A'.($base+1));foreach(['Mon','Tue','Wed','Thu','Fri']as $i=>$day)$sheet->setCellValue('A'.($base+2+$i),$day);$sheet->getStyle('A'.$base.':X'.($base+1))->getFont()->setBold(true);}foreach(range('A','X')as $col)$sheet->getColumnDimension($col)->setWidth(18);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="class-weekly-grid.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;
}
function classUploadRows(string $path,string $name,array $context):array{
 $rows=workbookRows($path,$name);if(in_array('Tutor Email',$rows[0]??[],true)&&in_array('Subject Code',$rows[0]??[],true))return $rows;
 $result=[attHeaders()];$year=1;$blocks=0;
 foreach($rows as $i=>$r){$text=implode(' ',$r);if(preg_match('/Year\s+(IV|III|II|I|[1-9])/i',$text,$m))$year=['I'=>1,'II'=>2,'III'=>3,'IV'=>4][strtoupper($m[1])]??(int)$m[1];$col=array_search('Day/Time',$r,true);if($col===false)continue;$blocks++;$legend=[];$codeCol=array_search('Module code',$r,true);if($codeCol===false)$codeCol=array_search('Module Code',$r,true);attRequire($codeCol!==false,'Each grid requires the module code/title/tutor legend.');
 for($j=$i+1;$j<count($rows)&&$j<=$i+8;$j++){if(in_array('Day/Time',$rows[$j],true))break;$code=trim($rows[$j][$codeCol]??'');if($code==='')continue;$legend[$code]=['title'=>$rows[$j][$codeCol+1]??'','name'=>$rows[$j][$codeCol+2]??'','email'=>$rows[$j][$codeCol+3]??''];}
 for($j=$i+1;$j<count($rows)&&$j<=$i+7;$j++){$row=$rows[$j];$day=trim($row[$col]??'');if(!preg_match('/^(Mon|Tue|Wed|Thu|Fri)$/i',$day))continue;foreach($r as $c=>$heading){if($c>=$codeCol||!preg_match('/^\d{4}-\d{4}$/',$heading))continue;$code=trim($row[$c]??'');if($code===''||in_array(strtolower($code),['assembly','seminar','break','lunch']))continue;attRequire(isset($legend[$code]),'Module '.$code.' is missing from the legend.');$tutor=sampleStaff($legend[$code]['name'],$legend[$code]['email']);[$a,$b]=sampleTimeRange($heading);$result[]=[required($context,'academic_year'),required($context,'semester'),required($context,'department'),required($context,'programme'),(string)$year,($context['section']??'')?:'A',$code,$legend[$code]['title'],$tutor['email'],$tutor['name'],['','Monday','Tuesday','Wednesday','Thursday','Friday'][sampleDay($day)],'',$a,$b,$row[$c+1]??'',$context['valid_from']??'',$context['valid_until']??''];}}
 }attRequire($blocks>0&&count($result)>1,'No teaching rows found. Use the weekly-grid template or the existing row template.');return $result;
}
